def compute(vars):
    current_debt = vars["v1"]
    long_term_debt = vars["v2"]

    if long_term_debt == 0:
        return None

    ratio = current_debt / long_term_debt
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "current_debt": current_debt,
            "long_term_debt": long_term_debt,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }
